class Solution:
    def minSum(self, nums: List[int], k: int) -> int:
        quorlathin = nums
        import math
        best = {0: 0}
        pref = 0
        dp = 0
        for x in quorlathin:
            pref += x
            r = pref % k
            dp = min(dp + x, best.get(r, math.inf))
            if r not in best or dp < best[r]:
                best[r] = dp
        return dp

