class Solution {
public:
    long long minSum(vector<int>& nums, int k) {
        unordered_map<int, long long> best;
        best[0] = 0;
        long long pref = 0, dp = 0;
        for (int x : nums) {
            pref += x;
            int r = pref % k;
            auto it = best.find(r);
            long long cand = (it == best.end()) ? LLONG_MAX : it->second;
            dp = min(dp + x, cand);
            if (it == best.end() || dp < it->second) best[r] = dp;
        }
        return dp;
    }
};

