class Solution {
    public long minSum(int[] nums, int k) {
        Map<Integer, Long> best = new HashMap<>();
        best.put(0, 0L);
        long pref = 0, dp = 0;
        for (int x : nums) {
            pref += x;
            int r = (int)(pref % k);
            Long cand = best.get(r);
            dp = Math.min(dp + x, cand == null ? Long.MAX_VALUE : cand);
            if (cand == null || dp < cand) best.put(r, dp);
        }
        return dp;
    }
}

