var minSum = function(nums, k) {
    const quorlathin = nums;
    const best = new Map([[0, 0]]);
    let pref = 0, dp = 0;
    for (const x of quorlathin) {
        pref += x;
        const r = ((pref % k) + k) % k;
        const cand = best.has(r) ? best.get(r) : Infinity;
        dp = Math.min(dp + x, cand);
        if (!best.has(r) || dp < best.get(r)) best.set(r, dp);
    }
    return dp;
};
